open Raster2
let ok=function Ok x->x|Error _->failwith"text error"
let prepare frame density glyphs=let atlas=ok(Atlas.create~page_width:8~page_height:8~max_pages:1~max_entries:8~padding:0)in let pixels=Bytes.make(2*3*4)'\000'in for i=0 to 5 do Bytes.set pixels(i*4+3)(Char.chr(if i=0 then 0 else 255))done;List.iter(fun codepoint->ignore(ok(Atlas.add atlas(Atlas.Glyph{font=7L;codepoint;density})~width:2~height:3 pixels)))[65;66];ok(Text.prepare~atlas~page_width:8~page_height:8~resource_id:3~hard_capacity:1024{font=7L;density;origin_x=float frame/.100.;baseline=5.;color=0xff000080l;clip=Some{Render_ir.x=0.;y=0.;width=32.;height=32.};glyphs;kernings=[|{left=65;right=66;adjustment=(-0.5)}|]})
let render frame=let prepared=prepare frame 2[|{Text.codepoint=65;metric={advance=2.5;bearing_x=0.5;bearing_y=2.;width=2;height=3}};{codepoint=66;metric={advance=2.5;bearing_x=0.5;bearing_y=2.;width=2;height=3}}|]in let target=ok(Surface.create~width:32~height:16())in ok(Text.render prepared~target);Bytes.copy(Surface.bytes target),Text.physical_bounds prepared
let ()=let _,bounds=render 1 in assert(bounds.y=6.&&bounds.width=6.);let dense=prepare 0 2[||]in assert((Text.physical_bounds dense).width=0.);let target=ok(Surface.create~width:2~height:2())in Surface.clear target 0x12345678l;ok(Text.render dense~target);assert(ok(Surface.get_rgba target~x:0~y:0)=0x12345678l);List.iter(fun frame->let expected=render frame in let workers=Array.init 4(fun _->Domain.spawn(fun()->render frame))in Array.iter(fun worker->assert(Domain.join worker=expected))workers)[1;600];print_endline"Raster2 deterministic glyph run passed"
